#!/usr/bin/env python3
# Expands the Prompt Components workspace: 15 categories, 174 blocks, 43 frameworks.
import sys

with open('static/app.js', 'r', encoding='utf-8') as f:
    content = f.read()

start_marker = '\n  var CATEGORIES = ['
end_marker = '\n\n  var _canvasBlocks = [];'

start_pos = content.find(start_marker)
end_pos = content.find(end_marker, start_pos)

if start_pos == -1 or end_pos == -1:
    print('ERROR: section markers not found')
    sys.exit(1)

